var RULES = [[/CCI|MFI|ultimate/i, "rsi_svg"], [/ROC|TSI|awesome/i, "macd_svg"], [/volatilit/i, "bollinger"], [/ease of movement/i, "volume"], [/score|confiance|biais/i, "cone_svg"], [/stochastique|williams/i, "stochastique"], [/RSI|surachat/i, "rsi_svg"], [/^(SMA|EMA|HMA)|moyenne mobile/i, "mm_svg"], [/MACD/, "macd_svg"], [/divergence/i, "divergence"], [/ichimoku/i, "ichimoku"], [/bollinger|keltner|donchian|cart-type/i, "bollinger"], [/stop|take profit|ATR/i, "stop"], [/VWAP/, "vwap"], [/volume|OBV|chaikin|accumulation|force index|klinger/i, "volume"], [/fibonacci/i, "fibo_svg"], [/corr[ée]lation|b[êe]ta|force relative/i, "correlation"], [/monte|intervalle|m[ée]diane|probabilit/i, "cone_svg"], [/chandelier|doji|marteau|harami/i, "candles_svg"], [/ADX|DMI|choppiness|aroon/i, "regimes"], [/pivot|support|r[ée]sistance/i, "sr_svg"], [/supertrend|SAR|tendance/i, "tendance"]];

export function diagramFor(term) {
  for (var i = 0; i < RULES.length; i++) if (RULES[i][0].test(term)) return DIAGRAMS[RULES[i][1]] || null;
  return null;
}
